/* Hand-authored Day 074–080. Helpers shape data only; all prose is topic-specific. */
const fs=require('fs'),path=require('path'),days={};
for(let id=74;id<=80;id++)days[id]=JSON.parse(fs.readFileSync(path.join(__dirname,'..','data',`day-${String(id).padStart(3,'0')}.json`),'utf8'));
const V=(word,ipa,meaning,collocation,collocationCN)=>({word,ipa,meaning,collocation,collocationCN});
const P=(base,a,b,c,note)=>({base,options:[a,b,c],note});
const S=(pattern,cn,example)=>({pattern,cn,example}),E=(text,cn,example)=>({text,cn,example}),M=(wrong,correct,why)=>({wrong,correct,why});
const W=(viewpoint,topicSentence,collocations,argument)=>({viewpoint,topicSentence,collocations,argument});
const Q=(type,prompt,answer,explanation,options)=>Object.assign({type,prompt,answer,explanation},options?{options}:{});
const set=(id,x)=>Object.assign(days[id],x);

set(74,{vocabulary:[
V('municipal waste','/mjuːˈnɪsɪpəl weɪst/','城市生活垃圾','collect municipal waste','收集城市生活垃圾'),V('landfill','/ˈlændfɪl/','垃圾填埋场','divert waste from landfill','使垃圾免于填埋'),V('recyclable','/ˌriːˈsaɪkləbəl/','可回收的','recyclable packaging','可回收包装'),V('contamination','/kənˌtæmɪˈneɪʃən/','污染；混入杂物','reduce recycling contamination','减少回收物污染'),V('compost','/ˈkɒmpɒst/','堆肥','turn food scraps into compost','把厨余变成堆肥'),V('single-use','/ˌsɪŋɡəl ˈjuːs/','一次性的','phase out single-use plastics','逐步淘汰一次性塑料'),V('collection scheme','/kəˈlekʃən skiːm/','收集计划','run a kerbside collection scheme','实行路边回收计划'),V('sorting facility','/ˈsɔːtɪŋ fəˌsɪləti/','分拣设施','upgrade a sorting facility','升级分拣设施'),V('circular economy','/ˌsɜːkjələr ɪˈkɒnəmi/','循环经济','move towards a circular economy','迈向循环经济'),V('recover materials','/rɪˈkʌvə məˈtɪəriəlz/','回收材料','recover valuable materials','回收有价值的材料'),V('product lifespan','/ˈprɒdʌkt ˈlaɪfspæn/','产品寿命','extend a product’s lifespan','延长产品寿命'),V('repairable','/rɪˈpeərəbəl/','可维修的','design repairable appliances','设计可维修电器'),V('disposable','/dɪˈspəʊzəbəl/','用后即弃的','avoid disposable items','避免一次性用品'),V('deposit-return scheme','/dɪˈpɒzɪt rɪˌtɜːn skiːm/','押金返还制度','introduce a deposit-return scheme','引入押金返还制度'),V('separate waste','/ˈsepəreɪt weɪst/','垃圾分类','separate waste at home','在家进行垃圾分类'),V('cut down on waste','/kʌt daʊn ɒn weɪst/','减少垃圾','cut down on food waste','减少食物浪费'),V('throw something away','/θrəʊ ˌsʌmθɪŋ əˈweɪ/','扔掉某物','think before throwing it away','扔掉前先考虑'),V('use something up','/juːz ˌsʌmθɪŋ ˈʌp/','用完某物','use up leftovers','吃完剩饭'),V('collection day','/kəˈlekʃən deɪ/','垃圾收集日','put the bins out on collection day','收集日把垃圾桶推出去'),V('waste hierarchy','/weɪst ˈhaɪərɑːki/','废物管理层级','follow the waste hierarchy','遵循废物管理层级')],
paraphrases:[P('reduce waste','prevent waste','cut waste generation','minimise discarded material','prevent强调从源头避免，minimise适合正式写作。'),P('recycle','reprocess','recover materials from','return to productive use','reprocess强调工业处理过程。'),P('throw away','discard','dispose of','send to waste','dispose of较正式，后接具体物品。'),P('too much packaging','excessive packaging','unnecessary wrapping','an overuse of packaging','excessive可直接用于Task 2批评过度包装。'),P('household rubbish','domestic waste','residential refuse','waste produced at home','domestic waste是常见学术搭配。'),P('reuse products','use items again','give products a second life','keep goods in circulation','keep goods in circulation适合循环经济语境。'),P('make producers responsible','extend producer responsibility','hold manufacturers accountable','shift disposal costs to producers','三种表达侧重点分别是制度、问责和成本。'),P('a recycling system','a recovery programme','a material-collection network','a resource-recovery system','resource recovery比单纯recycling范围更广。')],
sentences:[S('Rather than treating + discarded item + as waste, + actor + can + recovery action.','与其把某种废弃物当作垃圾，相关主体可以采取回收利用措施。','Rather than treating old laptops as waste, repair centres can recover working components.'),S('Whether + material + can be recycled depends less on + common assumption + than on + practical condition.','某种材料能否回收，与其说取决于通常的假设，不如说取决于实际条件。','Whether plastic can be recycled depends less on its symbol than on the facilities available locally.'),S('Only when + collection condition + does + desired recycling outcome.','只有满足某种收集条件，理想的回收结果才会出现。','Only when food residue is removed does recycled paper retain sufficient quality.')],
expressions:[E('put the recycling out','把回收物拿出去等待收集','I put the recycling out before leaving for work.'),E('give it a second life','让某物得到二次利用','Repairing the chair gave it a second life.'),E('end up in landfill','最终进入填埋场','Many usable objects still end up in landfill.'),E('reduce waste at source','从源头减少废物','Refill systems reduce waste at source.'),E('keep materials in circulation','让材料持续循环使用','Repair and resale keep materials in circulation.')],
mistakes:[M('This bottle can be recycled again and again forever.','This bottle can be recycled several times, although its quality may decline.','多数材料会降级，forever属于不准确的绝对化表达。'),M('We should classify the rubbish at home.','We should separate the rubbish at home.','日常垃圾分类通常用separate或sort，不用classify。'),M('There are many wastes in the bin.','There is a lot of waste in the bin.','表示废弃物总称时，waste通常不可数。')],
writingIdeas:[W('Prevention deserves priority over recycling.','Governments should focus first on preventing unnecessary waste rather than relying on recycling after consumption.',['prevent waste at source','extend product lifespans','discourage disposable consumption','reduce demand for raw materials'],'Recycling recovers some resources, but collection and reprocessing still require energy and infrastructure. Preventing an item from becoming waste avoids those costs altogether. For example, repair guarantees can keep appliances in use while refill services eliminate repeated packaging. Recycling remains necessary for unavoidable waste, yet it should follow reduction and reuse in the policy hierarchy.'),W('Producers should bear more end-of-life responsibility.','Making manufacturers responsible for discarded products can improve design as well as waste collection.',['extend producer responsibility','cover disposal costs','design for disassembly','create a financial incentive'],'At present, local taxpayers often fund the disposal of goods whose packaging and construction they did not choose. If producers must collect or finance those products at the end of their lives, difficult-to-recycle designs become more expensive. Manufacturers then have an incentive to reduce mixed materials and make components replaceable. Deposit schemes for bottles show how responsibility can also create a convenient return route. Carefully designed rules can therefore shift waste prevention upstream without removing consumer choice.')],
speaking:[{part:'Part 2',question:'Describe something you repaired instead of throwing away.',answer:'I repaired a desk lamp that had stopped working after several years. At first I assumed the whole lamp was broken, but a local repair shop found that only the switch needed replacing. The repair took about twenty minutes and cost far less than a new lamp. I was pleased because the metal body and shade were still in excellent condition, so throwing them away would have made no sense. Since then, I have become more willing to ask whether an object has one faulty part rather than treating it as completely useless. I still replace things when repair is unsafe or impractical, but that small experience made repair feel like a normal option rather than a specialist hobby.'},{part:'Part 3',question:'Why do some people fail to recycle even when collection services are available?',answer:'Convenience is only part of the explanation. People may be unsure which materials belong in each bin, especially when labels vary between neighbourhoods or packaging combines several materials. Limited space in small homes can also make sorting difficult. In addition, some residents doubt that separated waste is genuinely recycled, so they see little value in making an effort. Clear instructions, reliable collection and honest reporting about what happens afterwards can address these barriers. Penalties alone are unlikely to work if the system itself remains confusing.'}],
reading:{title:'What a Recycling Symbol Cannot Tell You',paragraphs:[
'A triangle of arrows on a package appears to offer a simple instruction: recycle this item. In practice, the symbol may identify the type of plastic rather than confirm that a local service accepts it. Residents who place every marked package in a recycling bin are therefore acting reasonably, yet their well-intentioned decisions can create contamination at sorting facilities.',
'Local variation explains much of the confusion. A council that has a buyer for clear plastic trays may collect them, whereas a neighbouring authority, using different machinery and serving a smaller market, may reject the same objects. Packaging design changes faster than collection contracts, which are often agreed for several years. Consequently, a label printed for a national market cannot always describe a recycling route that depends on local equipment, transport costs and demand for recovered material.',
'Contamination is not merely an untidy bin. Food residue can damage paper fibres, and plastic film, wrapping itself around rotating equipment, may force a processing line to stop while workers remove it. Some facilities accept mixed recyclables because participation is higher when households use one container; others require separation because cleaner material commands a better price. Neither arrangement is automatically superior, although instructions must match the system actually operating.',
'Several governments are developing labels that combine material information with disposal guidance. For such labels to remain accurate, producers, retailers and waste authorities need a shared database that can reflect regional differences. Digital codes could provide local instructions, but requiring a phone to understand a packet would disadvantage some users. The essential message still needs to be visible at the moment of disposal.',
'Better labels will not solve weak markets for recovered material or make every composite package recyclable. They can, however, replace a hopeful symbol with a realistic action. That modest improvement matters: a recycling system works not when every object carries green arrows, but when people can identify the correct route and trust that the route leads somewhere useful.'
],questions:[Q('True / False / Not Given','A recycling symbol always confirms that a local authority accepts the package.','False','Paragraph 1 states that the symbol may only identify the plastic type.'),Q('Matching Information','Which paragraph explains why plastic film can interrupt machinery?','C','Paragraph C describes film wrapping around rotating equipment.'),Q('Sentence Completion','Cleaner recovered material may command a better ______.','price','Paragraph 3 states that cleaner material commands a better price.')]}});

set(75,{vocabulary:[V('particulate matter','/pɑːˈtɪkjələt ˈmætə/','颗粒物','measure fine particulate matter','测量细颗粒物'),V('nitrogen dioxide','/ˌnaɪtrədʒən daɪˈɒksaɪd/','二氧化氮','exposure to nitrogen dioxide','接触二氧化氮'),V('vehicle emissions','/ˈviːəkəl ɪˈmɪʃənz/','车辆排放','curb vehicle emissions','遏制车辆排放'),V('airborne','/ˈeəbɔːn/','空气传播的','airborne pollutants','空气中的污染物'),V('respiratory','/rɪˈspɪrətri/','呼吸系统的','respiratory illness','呼吸系统疾病'),V('exposure','/ɪkˈspəʊʒə/','暴露','limit long-term exposure','限制长期暴露'),V('monitoring station','/ˈmɒnɪtərɪŋ ˌsteɪʃən/','监测站','install a monitoring station','安装监测站'),V('air-quality index','/eə ˈkwɒləti ˌɪndeks/','空气质量指数','check the air-quality index','查看空气质量指数'),V('low-emission zone','/ləʊ ɪˈmɪʃən zəʊn/','低排放区','enforce a low-emission zone','实施低排放区'),V('industrial plume','/ɪnˈdʌstriəl pluːm/','工业烟羽','track an industrial plume','追踪工业烟羽'),V('prevailing wind','/prɪˈveɪlɪŋ wɪnd/','盛行风','follow the prevailing wind','顺着盛行风'),V('indoor air quality','/ˈɪndɔː eə ˌkwɒləti/','室内空气质量','improve indoor air quality','改善室内空气质量'),V('ventilation','/ˌventɪˈleɪʃən/','通风','ensure adequate ventilation','确保充分通风'),V('idling','/ˈaɪdlɪŋ/','怠速运转','discourage engine idling','劝阻发动机怠速'),V('pollution hotspot','/pəˈluːʃən ˌhɒtspɒt/','污染热点','identify a pollution hotspot','识别污染热点'),V('take a different route','/teɪk ə ˈdɪfərənt ruːt/','换一条路线','take a quieter route to work','走更安静的路上班'),V('keep the windows shut','/kiːp ðə ˈwɪndəʊz ʃʌt/','关紧窗户','keep the windows shut at rush hour','高峰期关窗'),V('poor air day','/pʊə eə deɪ/','空气质量差的一天','avoid exercise on a poor air day','空气差时避免锻炼'),V('clean-air policy','/kliːn eə ˈpɒləsi/','清洁空气政策','adopt a clean-air policy','采取清洁空气政策'),V('health burden','/helθ ˈbɜːdən/','健康负担','reduce the health burden','减轻健康负担')],paraphrases:[P('dirty air','air pollution','polluted air','poor air quality','poor air quality最适合正式报告。'),P('harm health','damage health','increase health risks','contribute to illness','contribute to避免声称单一原因。'),P('measure pollution','monitor air quality','record pollutant levels','track atmospheric contamination','monitor强调持续观测。'),P('traffic fumes','vehicle exhaust','road-transport emissions','pollutants from motor vehicles','road-transport emissions适合政策讨论。'),P('people living nearby','local residents','nearby communities','populations in the surrounding area','populations常用于研究报告。'),P('reduce emissions','curb emissions','cut pollutant output','lower the release of contaminants','curb含控制上升趋势之意。'),P('unequal exposure','an exposure gap','environmental inequality','uneven pollution burdens','burden突出后果分配。'),P('fresh air','cleaner air','air with fewer pollutants','improved ambient air quality','ambient air quality是学术表达。')],sentences:[S('Although + citywide measure + has fallen, residents near + source + may still experience + local risk.','尽管全市指标已经下降，污染源附近居民仍可能面临局部风险。','Although average pollution has fallen, residents near freight routes may still experience dangerous peaks.'),S('The pollutants to which + group + is exposed are shaped by both + place + and + routine.','某群体接触的污染物同时受到地点和日常活动影响。','The pollutants to which schoolchildren are exposed are shaped by both classroom location and travel routines.'),S('By + non-finite action, authorities can + outcome + without + unwanted consequence.','通过采取某种措施，管理部门可以在避免不良后果的同时取得成效。','By redirecting heavy vehicles, authorities can protect residential streets without restricting essential deliveries.')],expressions:[E('the air feels heavy','感觉空气很闷','The air feels heavy beside the main road.'),E('avoid the rush-hour fumes','避开高峰期尾气','I cycle earlier to avoid the rush-hour fumes.'),E('leave the engine running','让发动机一直运转','Drivers should not leave the engine running outside schools.'),E('improve ambient air quality','改善环境空气质量','Cleaner buses improve ambient air quality.'),E('bear a disproportionate burden','承受不成比例的负担','Low-income districts often bear a disproportionate pollution burden.')],mistakes:[M('The air is badly today.','The air quality is poor today.','badly是副词；描述空气质量应用形容词poor。'),M('Factories produce many pollutions.','Factories produce a great deal of pollution.','pollution通常不可数。'),M('Traffic fumes cause people suffer from asthma.','Traffic fumes cause people to suffer from asthma.','cause somebody to do是固定结构。')],writingIdeas:[W('Air-quality policy should target exposure, not only averages.','Citywide improvements can conceal severe pollution experienced by particular streets and groups.',['measure local exposure','identify pollution hotspots','protect vulnerable residents','publish neighbourhood-level data'],'A falling urban average may look successful even while schools beside major roads experience repeated peaks. Because health risk depends on where people spend time, fixed monitors should be supplemented by local and mobile measurements. Authorities can then redirect traffic, alter delivery times or improve filtration where exposure is greatest. This targeted approach uses evidence more fairly than applying an identical intervention everywhere. Success should be judged by whether the most exposed communities benefit, not simply by one citywide figure.'),W('Clean transport zones need complementary support.','Restricting high-emission vehicles is effective only when households and businesses have realistic alternatives.',['introduce an emissions zone','upgrade commercial fleets','provide transitional support','maintain essential access'],'A charge can accelerate the replacement of polluting vehicles, but the immediate cost falls unevenly. A small business with one old van may struggle more than a large operator that routinely renews its fleet. Time-limited grants and reliable public transport can reduce that imbalance while preserving the incentive to change. Exemptions should remain narrow, or the environmental benefit will disappear. Combining a firm deadline with practical transition support is therefore both fairer and more likely to secure compliance.')],speaking:[{part:'Part 2',question:'Describe a place where you noticed poor air quality.',answer:'I noticed it most clearly at a bus stop beside a wide road during the evening rush hour. Several buses and delivery vehicles were waiting with their engines running, and the air had a sharp smell that caught in my throat. What surprised me was how different it felt from a park only two streets away. I checked an air-quality app later, although its nearest monitor was quite distant, so it could not describe that exact corner. Since then, I have used a quieter parallel street when I walk home. The experience made air pollution feel local and immediate rather than like an abstract citywide statistic.'},{part:'Part 3',question:'Should individuals change their routines when air pollution is high?',answer:'Short-term precautions can be sensible, especially for children, older people and anyone with a respiratory condition. For instance, someone might exercise away from traffic or ventilate a room at a cleaner time of day. However, people cannot be expected to solve polluted air by constantly avoiding it. Many workers have fixed routes and hours, and not everyone can move home. Public authorities and major emitters therefore carry the main responsibility for reducing pollution at source, while clear advice helps residents manage unusual peaks.'}],reading:{title:'The Pollution Map Drawn by a School Day',paragraphs:['Official monitors provide essential long-term records, but their small number can make pollution appear smoother than it is. A research team studying children’s exposure in one city therefore attached lightweight sensors to school bags. The aim was not to replace calibrated stations; it was to discover how pollution changed along the routes and indoor spaces that shaped an ordinary day.','The readings rose beside congested junctions and fell in streets separated from traffic by buildings. Yet distance alone did not explain the pattern. At one school, a playground set back from the road recorded short peaks when parents left engines running at the gate, while a classroom facing a quieter courtyard accumulated carbon dioxide because its windows remained closed. The study thus distinguished outdoor pollutants from poor ventilation, two problems requiring different remedies.','Personal sensors produce messy evidence. Movement, humidity and the position of a device can affect a reading, and children following different routes cannot be treated as a controlled laboratory sample. Researchers corrected the instruments against a fixed station and combined repeated journeys rather than interpreting one dramatic peak. The resulting map, while less precise at any single second, revealed consistent places where exposure increased.','Schools used the findings in varied ways. One changed the time at which delivery vehicles entered; another opened a walking entrance away from the main road. A third improved classroom ventilation after staff realised that keeping every window shut against traffic had created a separate indoor problem. None of these measures required families to abandon the neighbourhood.','The project’s larger lesson concerns measurement. An annual city average can show whether broad policy is working, whereas a child’s route reveals where practical protection is possible now. These forms of evidence are not competitors. Joined carefully, they connect regional emission controls with the small decisions—about gates, engines and windows—through which cleaner air becomes part of daily life.'],questions:[Q('Multiple Choice','Why did researchers attach sensors to school bags?','B','They wanted to measure variation across children’s daily routes and spaces.',['To replace every official monitoring station','To measure variation across daily routes and spaces','To test children in a controlled laboratory','To compare school examination results']),Q('Yes / No / Not Given','The researchers interpreted each isolated pollution peak as reliable evidence.','No','Paragraph 3 says they combined repeated journeys rather than one dramatic peak.'),Q('Short Answer','What caused carbon dioxide to accumulate in one classroom?','closed windows','Paragraph 2 explains that the windows remained closed.')]}});

set(76,{vocabulary:[V('greenhouse gas','/ˈɡriːnhaʊs ɡæs/','温室气体','cut greenhouse-gas emissions','减少温室气体排放'),V('global warming','/ˌɡləʊbəl ˈwɔːmɪŋ/','全球变暖','limit global warming','限制全球变暖'),V('climate model','/ˈklaɪmət ˌmɒdəl/','气候模型','run a climate model','运行气候模型'),V('mitigation','/ˌmɪtɪˈɡeɪʃən/','减缓','climate mitigation measures','气候减缓措施'),V('adaptation','/ˌædæpˈteɪʃən/','适应','invest in climate adaptation','投资气候适应'),V('resilience','/rɪˈzɪliəns/','韧性','strengthen coastal resilience','增强沿海韧性'),V('sea-level rise','/ˈsiː levəl raɪz/','海平面上升','prepare for sea-level rise','为海平面上升做准备'),V('extreme weather','/ɪkˌstriːm ˈweðə/','极端天气','face more extreme weather','面对更多极端天气'),V('carbon budget','/ˈkɑːbən ˌbʌdʒɪt/','碳预算','stay within a carbon budget','控制在碳预算内'),V('decarbonise','/diːˈkɑːbənaɪz/','脱碳','decarbonise electricity generation','使发电脱碳'),V('climate projection','/ˈklaɪmət prəˌdʒekʃən/','气候预测','use a regional climate projection','使用区域气候预测'),V('heatwave','/ˈhiːtweɪv/','热浪','cope with a prolonged heatwave','应对持续热浪'),V('carbon sink','/ˈkɑːbən sɪŋk/','碳汇','protect a natural carbon sink','保护自然碳汇'),V('tipping point','/ˈtɪpɪŋ pɔɪnt/','临界点','cross a climatic tipping point','越过气候临界点'),V('climate finance','/ˈklaɪmət ˌfaɪnæns/','气候资金','mobilise climate finance','调动气候资金'),V('future-proof','/ˈfjuːtʃə pruːf/','使适应未来','future-proof public infrastructure','使公共设施适应未来'),V('weather the storm','/ˈweðə ðə stɔːm/','渡过难关','help communities weather the storm','帮助社区渡过难关'),V('plan ahead','/plæn əˈhed/','提前规划','plan ahead for hotter summers','为更热夏季提前规划'),V('make a low-carbon choice','/meɪk ə ləʊ ˈkɑːbən tʃɔɪs/','作出低碳选择','make a low-carbon travel choice','选择低碳出行'),V('shared responsibility','/ʃeəd rɪˌspɒnsəˈbɪləti/','共同责任','recognise shared responsibility','承认共同责任')],paraphrases:[P('climate change','a changing climate','long-term climatic change','human-driven climate disruption','human-driven明确人为因素。'),P('cut carbon emissions','decarbonise','reduce greenhouse-gas output','lower the carbon intensity of','carbon intensity适合比较单位产出。'),P('prepare for impacts','adapt to change','build climate resilience','anticipate unavoidable effects','adaptation并不等于放弃减排。'),P('hotter weather','rising temperatures','a warming climate','higher average and extreme temperatures','最后一项同时涵盖均值与极端值。'),P('uncertain forecast','a range of projections','model uncertainty','several plausible future scenarios','uncertainty不表示完全无知。'),P('poor countries','lower-income countries','climate-vulnerable states','nations with limited adaptive capacity','避免使用带判断色彩的poor countries。'),P('act now','take early action','accelerate the response','bring forward investment','bring forward表示提前实施。'),P('cost of delay','the price of inaction','higher future adjustment costs','the burden created by postponed action','inaction适合议论文。')],sentences:[S('Even if + mitigation target + is met, + adaptation measure + will remain necessary because + reason.','即使减排目标实现，适应措施仍然必要，因为某些影响已经无法完全避免。','Even if global emissions peak soon, heat adaptation will remain necessary because past emissions continue to affect the climate.'),S('What climate models provide is not + false certainty + but + useful range.','气候模型提供的不是虚假的确定性，而是有用的范围。','What climate models provide is not a single guaranteed future but a range within which planners can test decisions.'),S('Infrastructure built today, much of which will remain in use for + period, must + future condition.','今天建设的基础设施，其中许多将使用一段很长时间，必须适应未来条件。','Infrastructure built today, much of which will remain in use for decades, must withstand temperatures outside the historical range.')],expressions:[E('feel the effects first-hand','切身体会影响','Farmers are already feeling climate effects first-hand.'),E('prepare for the worst','为最坏情况做准备','Cities should prepare for the worst without assuming it is inevitable.'),E('lock in emissions','锁定未来排放','New coal plants can lock in emissions for decades.'),E('build climate resilience','增强气候韧性','Cool roofs can build climate resilience in dense districts.'),E('keep warming within limits','把升温控制在一定范围','Rapid cuts are needed to keep warming within agreed limits.')],mistakes:[M('Climate is changing every day.','The weather changes every day, while the climate changes over longer periods.','weather指短期天气，climate指长期统计规律。'),M('Global warming makes more natural disasters.','Climate change can increase the frequency or severity of some hazards.','不能笼统声称气候变化制造所有自然灾害。'),M('Governments must adapt with climate change.','Governments must adapt to climate change.','adapt to是固定搭配。')],writingIdeas:[W('Mitigation and adaptation are complementary.','Governments must reduce future warming while preparing for climatic changes that can no longer be avoided.',['cut future emissions','manage unavoidable impacts','coordinate public investment','avoid preventable losses'],'Mitigation addresses the cause by limiting greenhouse-gas emissions, whereas adaptation reduces harm from effects already emerging. Treating the two as alternatives creates a false choice: flood barriers cannot prevent continued warming, and emissions cuts cannot remove next summer’s heat risk. A city might therefore electrify buses while expanding shade and heat-health warnings. The balance of spending will differ by location, but both objectives require early planning. Integrated investment can also prevent an adaptation measure, such as energy-intensive cooling, from undermining mitigation.'),W('Climate finance should reflect unequal responsibility and capacity.','Higher-income countries have both a stronger ability and a historical obligation to support climate action elsewhere.',['provide concessional finance','address historical emissions','strengthen adaptive capacity','fund locally led projects'],'Many climate-vulnerable states contributed relatively little to accumulated emissions yet face severe adaptation costs. If limited domestic budgets are diverted from health or education, the burden of an international problem becomes still more unequal. Wealthier countries can provide grants and affordable finance for resilient infrastructure and clean energy. Funding should support priorities identified locally rather than impose unsuitable imported projects. Such cooperation is not charity alone; unmanaged climate disruption can also affect trade, migration and stability across borders.')],speaking:[{part:'Part 2',question:'Describe a change made in your area because of hotter weather.',answer:'My local library changed its summer opening arrangements after several unusually hot periods. It now opens earlier on days when extreme heat is forecast, keeps one large room available as a cool public space and provides drinking-water stations. The building already had good insulation, so the main changes involved staffing and communication rather than expensive construction. Older residents seem to value the service most, particularly those whose homes become uncomfortable in the afternoon. I like the fact that it uses an existing public building instead of creating a separate emergency facility. It is a modest adaptation, but it shows how climate planning can improve an ordinary service for people who need it.'},{part:'Part 3',question:'Why is it difficult for governments to make long-term climate decisions?',answer:'The benefits of prevention may appear decades later, whereas the costs of a policy are visible immediately to voters and businesses. Climate projections also describe a range rather than one exact local outcome, which can make delay seem reasonable. In addition, responsibility crosses ministries and national borders, so no institution controls the whole problem. Governments can manage this difficulty by setting durable targets, reviewing evidence regularly and choosing investments that perform well under several future conditions. Uncertainty should influence the design of action, not become an excuse for doing nothing.'}],reading:{title:'Planning a Bridge for a Climate That Has Not Arrived',paragraphs:['Engineers traditionally design bridges using records of past river flow, temperature and wind. Climate change weakens the assumption behind that practice: a structure expected to last eighty years will operate under conditions partly outside the record used to design it. The challenge is not to predict the exact weather on a future date, but to make an expensive, long-lived asset reliable across several plausible climates.','One response is to select the most severe projection and build for it immediately. This may appear cautious, yet excessive initial construction consumes materials, raises emissions and can divert money from other safety needs. Using only the middle projection carries a different risk, because an average scenario may conceal a low-probability outcome with catastrophic consequences. Engineers therefore examine both the consequence of failure and the cost of adding protection.','Adaptive design offers a third approach. Foundations can be built strong enough for a higher deck, while the deck itself is raised only if monitoring shows faster sea-level rise. Drainage channels may include space for later widening. Such decisions, which preserve a practical route for modification without purchasing every component now, are valuable where uncertainty will narrow over time. They are less suitable when later alteration would require closing the bridge for years.','Choosing trigger points is difficult. A single flood may be exceptional rather than evidence of a trend, while waiting for repeated damage defeats the purpose of preparation. Planners can combine observed sea level, updated regional models and the remaining time needed for construction. Crucially, responsibility and funding for the later stage must be agreed when the original project is approved; otherwise, an adaptable design may never be adapted.','Climate-ready engineering is therefore neither blind overbuilding nor passive waiting. It asks which decisions are irreversible, which can be postponed safely and what evidence should prompt change. A bridge designed in this way embodies a different kind of confidence—not certainty about one future, but confidence that institutions can recognise change and respond before the structure fails.'],questions:[Q('Matching Headings','Choose the best heading for Paragraph C.','Designing a route for later modification','Paragraph C explains adaptive design that preserves options for later changes.', ['The limits of historical records','Designing a route for later modification','Why all bridges should be rebuilt','Funding past flood damage']),Q('True / False / Not Given','Building immediately for the most severe projection has no environmental cost.','False','Paragraph 2 says excessive construction consumes materials and raises emissions.'),Q('Summary Completion','An adaptable design may fail in practice unless future responsibility and ______ are agreed.','funding','Paragraph 4 names responsibility and funding.')]}});

set(77,{vocabulary:[V('sustainable lifestyle','/səˈsteɪnəbəl ˈlaɪfstaɪl/','可持续生活方式','adopt a sustainable lifestyle','采取可持续生活方式'),V('conscious consumption','/ˈkɒnʃəs kənˈsʌmpʃən/','理性消费','practise conscious consumption','践行理性消费'),V('energy-efficient','/ˈenədʒi ɪˌfɪʃənt/','节能的','buy an energy-efficient appliance','购买节能电器'),V('public transport pass','/ˌpʌblɪk ˈtrænspɔːt pɑːs/','公交月票','use a public transport pass','使用公交月票'),V('plant-based','/ˈplɑːnt beɪst/','以植物为主的','eat more plant-based meals','多吃植物性餐食'),V('seasonal produce','/ˈsiːzənəl ˈprɒdjuːs/','应季农产品','choose seasonal produce','选择应季农产品'),V('household energy use','/ˈhaʊshəʊld ˈenədʒi juːs/','家庭能耗','monitor household energy use','监测家庭能耗'),V('water-saving','/ˈwɔːtə ˌseɪvɪŋ/','节水的','install a water-saving showerhead','安装节水花洒'),V('second-hand','/ˌsekənd ˈhænd/','二手的','buy furniture second-hand','购买二手家具'),V('refill station','/ˈriːfɪl ˌsteɪʃən/','补充装站','use a refill station','使用补充装站'),V('food miles','/ˈfuːd maɪlz/','食物里程','consider food miles','考虑食物里程'),V('environmental footprint','/ɪnˌvaɪrənˈmentəl ˈfʊtprɪnt/','环境足迹','shrink an environmental footprint','缩小环境足迹'),V('low-impact','/ˌləʊ ˈɪmpækt/','低环境影响的','choose a low-impact option','选择低影响方案'),V('greenwashing','/ˈɡriːnwɒʃɪŋ/','漂绿','recognise misleading greenwashing','识别误导性漂绿'),V('habit formation','/ˈhæbɪt fɔːˌmeɪʃən/','习惯养成','support habit formation','支持习惯养成'),V('bring a reusable cup','/brɪŋ ə riːˈjuːzəbəl kʌp/','自带可重复使用杯','remember to bring a reusable cup','记得自带杯'),V('make do with','/meɪk ˈduː wɪð/','凑合使用现有物品','make do with what I own','使用已有物品'),V('shop around','/ʃɒp əˈraʊnd/','货比三家','shop around for durable goods','选购耐用品时货比三家'),V('save on bills','/seɪv ɒn bɪlz/','节省账单开支','save on electricity bills','节省电费'),V('make informed decisions','/meɪk ɪnˌfɔːmd dɪˈsɪʒənz/','作出知情决定','make informed purchasing decisions','作出知情购买决定')],paraphrases:[P('live sustainably','adopt lower-impact habits','reduce one’s everyday footprint','make environmentally responsible choices','lower-impact避免声称零影响。'),P('buy less','reduce consumption','purchase fewer new goods','avoid unnecessary purchases','unnecessary突出不影响必要消费。'),P('green product','lower-impact product','environmentally preferable option','product marketed as sustainable','marketed as不等于确实环保。'),P('easy choice','convenient option','low-effort alternative','choice built into daily routines','built into routines强调系统设计。'),P('save energy','use less energy','improve energy efficiency','reduce household energy demand','efficiency不一定等于总用量下降。'),P('personal action','individual behaviour','household-level change','a consumer’s everyday choices','语域从正式到日常。'),P('lasting habit','durable behaviour change','a routine that persists','a practice maintained over time','persist适合研究描述。'),P('tell people the impact','provide clear impact information','make consequences visible','communicate the environmental trade-offs','trade-offs避免过度简化。')],sentences:[S('A sustainable choice is more likely to become routine when it is both + quality + and + quality.','当可持续选择同时具备两种实际品质时，它更可能成为日常习惯。','A sustainable choice is more likely to become routine when it is both affordable and convenient.'),S('Having + past participle + once, + person + may continue to + action + if + feedback.','在尝试过某种行为后，如果获得反馈，人们可能会继续行动。','Having monitored her electricity use once, a resident may continue to conserve energy if the savings remain visible.'),S('The claim that + product + is greener matters only insofar as + evidence condition.','声称某产品更环保，只有在证据条件成立时才有意义。','The claim that a detergent is greener matters only insofar as its full ingredients and packaging are compared.')],expressions:[E('cut back on','减少','I am trying to cut back on unnecessary deliveries.'),E('get into the habit of','养成某习惯','I have got into the habit of carrying a bottle.'),E('use what I already have','使用已有物品','Before shopping, I check whether I can use what I already have.'),E('make a lower-impact choice','作出环境影响较低的选择','Clear labels help shoppers make a lower-impact choice.'),E('avoid shifting the burden','避免转移负担','A policy should avoid shifting the burden to low-income households.')],mistakes:[M('I live more environmental now.','I live in a more environmentally responsible way now.','environmental是形容词，不能直接修饰动词live。'),M('This bag is friendly to environment.','This bag is less harmful to the environment.','固定说法是environmentally friendly；更精确时可用less harmful。'),M('I have bought it from three years.','I have had it for three years.','持续拥有用have，时间段前用for。')],writingIdeas:[W('Sustainable habits spread when the better option is convenient.','Infrastructure and product design often influence household behaviour more reliably than moral appeals.',['remove practical barriers','make the default option sustainable','support lasting habits','provide convenient alternatives'],'Most people make repeated choices under time and budget pressure rather than after detailed environmental research. If buses are infrequent or refill points are distant, good intentions are unlikely to survive a busy week. By contrast, convenient collection, reliable transport and efficient appliances turn lower-impact behaviour into the easiest routine. Individuals still make choices, but the environment shapes how costly those choices feel. Policy should therefore combine information with practical systems that make sustainable living ordinary.'),W('Sustainable consumption can save money, but affordability is not automatic.','Environmental policies should distinguish between low-cost habits and investments that many households cannot make upfront.',['face an upfront cost','reduce running expenses','offer targeted assistance','share long-term savings'],'Using leftovers or buying fewer clothes costs little and may immediately save money. Home insulation and efficient heating, however, require capital even though they reduce future bills. A tenant may also lack authority to improve the building while paying its energy costs. Grants, landlord standards and affordable finance can solve this mismatch more effectively than advising residents to spend wisely. Sustainable living becomes fairer when people can access long-term savings regardless of their initial resources.')],speaking:[{part:'Part 2',question:'Describe an environmentally friendly habit that fits easily into your life.',answer:'The habit that fits most naturally is carrying a reusable water bottle. I began doing it mainly to avoid buying drinks while commuting, so the environmental benefit was not my only motivation. I leave the bottle beside my keys, which means I rarely forget it, and there are refill taps at my workplace. It saves a small amount of money and lets me see how much water I drink. I do not think this single habit has a dramatic effect, but it has lasted because it is convenient and useful. That has taught me that a sustainable routine is easier to maintain when it solves an everyday problem as well.'},{part:'Part 3',question:'Do environmental labels help people live more sustainably?',answer:'They can help when they compare products using clear and consistent criteria. A shopper cannot research every supply chain, so trustworthy labels reduce the effort required to make an informed decision. The problem is that vague claims such as “natural” or “green” may look official without explaining what was measured. Too many competing labels also create confusion. Independent standards, plain language and information about the whole product life cycle would make labels more useful, although price and availability will still shape the final choice.'}],reading:{title:'Why the Thermostat Display Changed Behaviour',paragraphs:['A housing association installed smart energy displays in two hundred flats, expecting residents to respond to real-time information about electricity use. Early results were disappointing. People watched the figures for several days, switched appliances off more carefully and then stopped looking. Information had created curiosity, but it had not become part of household routine.','Researchers interviewing residents found that the display showed energy in technical units that meant little without comparison. A number rising from 0.4 to 0.8 kilowatts appeared important, yet users did not know whether it reflected a wasteful appliance or normal cooking. The device also reported immediate consumption, whereas monthly bills combined energy price, standing charges and previous use. Residents could not easily connect one careful evening with money saved.','The association redesigned the feedback rather than adding more advice. The screen compared each flat with its own previous week, identified unusually high overnight use and estimated cost over a month. It did not rank neighbours, since flats differed in size and occupancy. Most importantly, residents could set one modest target and receive a message when a routine—such as reducing standby use—produced a measurable change.','Six months later, average electricity use had fallen, although the distribution was uneven. Households with old electric heating had limited control over their largest expense, and some residents found repeated messages irritating. Those who saved most were not necessarily the people most concerned about climate change; they were often users who discovered a specific source of avoidable cost and could act on it without sacrificing comfort.','The trial does not show that every home needs another digital screen. It demonstrates that feedback supports sustainable behaviour only when people can interpret it, connect it to an available action and see a relevant result. A number, however accurate, rarely changes a routine by itself. Information becomes useful when it helps a household decide what to do next.'],questions:[Q('Matching Information','Which paragraph explains why homes were not ranked against one another?','C','Paragraph C says flats differed in size and occupancy.'),Q('True / False / Not Given','Only residents already concerned about climate change reduced their electricity use.','False','Paragraph 4 says the largest savers were not necessarily the most climate-concerned.'),Q('Multiple Choice','What is the writer’s main conclusion?','D','Information changes routines when it is interpretable and linked to action.',['Technical units should be taught at school.','All homes require smart displays.','Neighbour rankings always save energy.','Feedback works when it is interpretable and actionable.'])]}});

set(78,{vocabulary:[V('biodiversity','/ˌbaɪəʊdaɪˈvɜːsəti/','生物多样性','conserve biodiversity','保护生物多样性'),V('species richness','/ˈspiːʃiːz ˌrɪtʃnəs/','物种丰富度','measure species richness','衡量物种丰富度'),V('habitat loss','/ˈhæbɪtæt lɒs/','栖息地丧失','reverse habitat loss','扭转栖息地丧失'),V('ecosystem','/ˈiːkəʊˌsɪstəm/','生态系统','restore a damaged ecosystem','修复受损生态系统'),V('ecological corridor','/ˌiːkəˈlɒdʒɪkəl ˈkɒrɪdɔː/','生态廊道','create an ecological corridor','建立生态廊道'),V('native species','/ˈneɪtɪv ˌspiːʃiːz/','本地物种','plant native species','种植本地物种'),V('invasive species','/ɪnˈveɪsɪv ˌspiːʃiːz/','入侵物种','control an invasive species','控制入侵物种'),V('pollinator','/ˈpɒləneɪtə/','传粉者','protect wild pollinators','保护野生传粉者'),V('genetic diversity','/dʒəˌnetɪk daɪˈvɜːsəti/','遗传多样性','maintain genetic diversity','维持遗传多样性'),V('food web','/ˈfuːd web/','食物网','disrupt a food web','扰乱食物网'),V('keystone species','/ˈkiːstəʊn ˌspiːʃiːz/','关键物种','identify a keystone species','识别关键物种'),V('population decline','/ˌpɒpjəˈleɪʃən dɪklaɪn/','种群下降','document a population decline','记录种群下降'),V('conservation status','/ˌkɒnsəˈveɪʃən ˈsteɪtəs/','保护状况','assess conservation status','评估保护状况'),V('habitat fragment','/ˈhæbɪtæt ˌfræɡmənt/','栖息地碎片','connect habitat fragments','连接栖息地碎片'),V('ecosystem service','/ˈiːkəʊsɪstəm ˌsɜːvɪs/','生态系统服务','value an ecosystem service','重视生态系统服务'),V('spot wildlife','/spɒt ˈwaɪldlaɪf/','发现野生动物','spot wildlife in the park','在公园看到野生动物'),V('leave an area undisturbed','/liːv ən ˈeəriə ˌʌndɪˈstɜːbd/','让区域不受干扰','leave nesting areas undisturbed','不打扰筑巢区域'),V('grow wild','/ɡrəʊ waɪld/','自然生长','let a corner grow wild','让一角自然生长'),V('raise awareness','/reɪz əˈweənəs/','提高意识','raise awareness of local species','提高对本地物种的认识'),V('evidence-based conservation','/ˈevɪdəns beɪst ˌkɒnsəˈveɪʃən/','循证保护','fund evidence-based conservation','资助循证保护')],paraphrases:[P('many species','high species richness','a diverse range of species','substantial biological diversity','richness是可测量概念。'),P('protect nature','conserve biodiversity','safeguard ecosystems','maintain ecological integrity','integrity强调系统结构与功能。'),P('loss of habitat','habitat destruction','the contraction of suitable habitat','declining habitat extent and quality','最后一项兼顾面积和质量。'),P('animals move between areas','species disperse across landscapes','wildlife travels between habitats','populations remain ecologically connected','connected强调基因交流。'),P('important species','ecologically significant species','a species with a disproportionate role','a keystone species','keystone不能泛指所有重要物种。'),P('nature helps people','ecosystems provide services','biodiversity supports human well-being','ecological processes generate public benefits','services可包括授粉、防洪等。'),P('numbers fall','populations decline','abundance decreases','a species undergoes sustained decline','abundance比species number准确。'),P('bring nature back','restore habitat','support ecological recovery','re-establish functioning ecosystems','restore不一定恢复到某个完美历史状态。')],sentences:[S('A site may contain + count + species while lacking + ecological quality + that enables them to + function.','某地可能拥有一定数量的物种，却缺乏让它们发挥功能的生态质量。','A park may contain many plant species while lacking the connected habitat that enables pollinators to survive year-round.'),S('The species on which + ecosystem/process + depends may not be the ones that + public visibility.','某生态系统所依赖的物种可能并不是最受公众关注的物种。','The species on which soil renewal depends may not be the ones that attract conservation campaigns.'),S('By reconnecting + fragmented places, + project + allows + population + to + benefit, thereby + wider result.','通过重新连接破碎区域，项目使种群获得益处，从而带来更广泛结果。','By reconnecting woodland fragments, the corridor allows mammals to disperse, thereby maintaining genetic diversity.')],expressions:[E('a haven for wildlife','野生动物的安居地','The wetland is a haven for migratory birds.'),E('let nature take its course','让自然按自身规律发展','In one section, managers let nature take its course.'),E('see a species in the wild','在野外看到某物种','I would love to see an otter in the wild.'),E('restore ecological connectivity','恢复生态连通性','Hedgerows can restore ecological connectivity.'),E('support a functioning ecosystem','维持正常运作的生态系统','Conservation should support a functioning ecosystem, not just a species list.')],mistakes:[M('Many animals are in danger to disappear.','Many animal species are at risk of disappearing.','固定搭配是at risk of doing。'),M('The biodiversity is important for human.','Biodiversity is important for humans.','泛指biodiversity不加the；human作名词通常用复数。'),M('We should protect wild lives.','We should protect wildlife.','wildlife是不可数集合名词，不能拆成wild lives。')],writingIdeas:[W('Habitat connectivity can outperform isolated protection.','Protected areas deliver limited benefits if wildlife cannot move between them.',['connect fragmented habitats','maintain genetic diversity','enable seasonal movement','plan across boundaries'],'A small reserve may protect breeding habitat yet leave feeding grounds or migration routes exposed. When roads and intensive land use isolate populations, genetic diversity can decline even inside a well-managed site. Corridors such as hedgerows, river margins and wildlife crossings allow movement between habitat fragments. The most effective route will depend on the target species rather than a standard strip of greenery. Conservation planning should therefore treat reserves as parts of a landscape network, not as self-contained islands.'),W('Urban biodiversity policy should prioritise ecological function over decorative variety.','A visually diverse planting scheme is not necessarily valuable to local wildlife.',['plant native vegetation','provide year-round resources','avoid intensive maintenance','support local food webs'],'A garden containing many ornamental species may offer little pollen, shelter or food for native insects. By contrast, fewer carefully selected plants can flower across seasons and support several stages of a pollinator’s life. Reducing pesticide use and leaving some dead wood may look less tidy but add essential habitat. Public explanation is important because residents may otherwise interpret ecological management as neglect. The goal should be a functioning urban ecosystem rather than the longest possible plant list.')],speaking:[{part:'Part 2',question:'Describe a place where you have seen interesting wildlife.',answer:'I have seen the most interesting wildlife at a wetland park on the edge of the city. A raised wooden path crosses shallow pools, so visitors can watch birds without entering their feeding areas. On my last visit, I saw a kingfisher for the first time. It appeared only briefly as a bright blue movement above the water, but a volunteer helped me identify it. I also noticed insects, frogs and plants that I would normally overlook. The park is not completely wild because water levels and visitor routes are managed, yet it feels much more alive than a decorative urban lake. That visit made me understand biodiversity as a network of ordinary species, not only rare animals.'},{part:'Part 3',question:'Why do conservation campaigns often focus on attractive animals?',answer:'An appealing animal gives a campaign a memorable image and makes an unfamiliar ecological problem easier to communicate. People may donate more readily to protect a tiger than a fungus or soil insect. This attention can benefit a wider habitat if the chosen animal needs a large and healthy ecosystem. However, funding can become distorted when appearance rather than ecological importance sets priorities. Campaigns should use familiar species as an entry point while explaining the less visible organisms and processes on which the whole system depends.'}],reading:{title:'The Meadow That Looked Untidy',paragraphs:['When a university stopped mowing several lawns every week, complaints arrived before the wildflowers did. Students described the long grass as neglected, and maintenance staff worried that litter would be harder to find. The project had been created to support insects, but its first challenge was cultural: for many users, short grass signalled care, whereas unmanaged height suggested that nobody was responsible.','Ecologists did not simply abandon the sites. They selected sunny areas connected to hedges, removed cut vegetation so that nutrient-loving grasses would not dominate and retained narrow mown paths. Surveys recorded plants and pollinators before the change and at fixed intervals afterwards. One lawn produced more flowers but few additional bee species because it remained isolated between buildings; another, adjoining gardens and a railway edge, became part of a longer foraging route.','The contrast altered the next phase. Rather than converting the greatest possible area, the team mapped where insects could move and where nesting material was available. Some small patches, positioned between larger habitats, were judged more useful than extensive but disconnected grass. This finding, which surprised administrators accustomed to measuring environmental projects by area, shifted attention from the quantity of meadow to its ecological relationship with surrounding land.','Public acceptance also improved once intention became visible. Low signs named several plants, while neatly cut borders showed that the longer vegetation was deliberate. The university kept open lawns for sport and social events instead of presenting biodiversity as the only valid use. Complaints declined, although some users still preferred the earlier appearance.','After four years, the project reported greater pollinator abundance in connected sites, not a universal increase everywhere. Its value lay partly in that uneven result. The campus became a field experiment showing that urban nature needs design, monitoring and explanation. Letting grass grow was the visible action; understanding where that action supported a functioning habitat was the more demanding work.'],questions:[Q('Summary Completion','The first challenge faced by the meadow project was primarily ______ rather than ecological.','cultural','Paragraph 1 explicitly calls the first challenge cultural.'),Q('Matching Information','Which paragraph describes administrators changing the way they measured the project?','C','Paragraph C says attention shifted from area to ecological relationships.'),Q('True / False / Not Given','Every converted lawn experienced an increase in bee species.','False','Paragraphs 2 and 5 state that results were uneven.')]}});

set(79,{vocabulary:[V('natural hazard','/ˈnætʃərəl ˌhæzəd/','自然灾害风险源','map a natural hazard','绘制自然灾害风险图'),V('disaster risk','/dɪˈzɑːstə rɪsk/','灾害风险','reduce disaster risk','降低灾害风险'),V('vulnerability','/ˌvʌlnərəˈbɪləti/','脆弱性','assess social vulnerability','评估社会脆弱性'),V('emergency response','/ɪˈmɜːdʒənsi rɪˌspɒns/','应急响应','coordinate emergency response','协调应急响应'),V('evacuation route','/ɪˌvækjuˈeɪʃən ruːt/','疏散路线','mark an evacuation route','标明疏散路线'),V('early-warning system','/ˌɜːli ˈwɔːnɪŋ ˌsɪstəm/','预警系统','operate an early-warning system','运行预警系统'),V('aftershock','/ˈɑːftəʃɒk/','余震','prepare for aftershocks','为余震做准备'),V('storm surge','/ˈstɔːm sɜːdʒ/','风暴潮','forecast a storm surge','预测风暴潮'),V('flash flood','/ˌflæʃ ˈflʌd/','山洪；突发洪水','issue a flash-flood warning','发布山洪预警'),V('building code','/ˈbɪldɪŋ kəʊd/','建筑规范','enforce a seismic building code','执行抗震建筑规范'),V('relief supplies','/rɪˈliːf səˌplaɪz/','救援物资','distribute relief supplies','分发救援物资'),V('temporary shelter','/ˈtempərəri ˌʃeltə/','临时住所','provide temporary shelter','提供临时住所'),V('recovery period','/rɪˈkʌvəri ˌpɪəriəd/','恢复期','shorten the recovery period','缩短恢复期'),V('preparedness drill','/prɪˈpeərədnəs drɪl/','应急演练','take part in a preparedness drill','参加应急演练'),V('risk communication','/rɪsk kəˌmjuːnɪˈkeɪʃən/','风险沟通','improve risk communication','改善风险沟通'),V('stock up on essentials','/stɒk ʌp ɒn ɪˈsenʃəlz/','储备必需品','stock up on basic essentials','储备基本用品'),V('keep a phone charged','/kiːp ə fəʊn tʃɑːdʒd/','保持手机有电','keep a phone fully charged','保持手机电量充足'),V('follow official advice','/ˈfɒləʊ əˈfɪʃəl ədˌvaɪs/','遵循官方建议','follow official evacuation advice','遵循官方疏散建议'),V('bounce back','/baʊns bæk/','恢复过来','help local businesses bounce back','帮助本地企业恢复'),V('build back better','/bɪld bæk ˈbetə/','灾后重建得更好','use recovery funds to build back better','用恢复资金改善重建')],paraphrases:[P('natural disaster','disaster caused by a natural hazard','hazard-related emergency','destructive event shaped by hazard and vulnerability','灾害不仅由自然过程决定。'),P('prepare for disaster','strengthen preparedness','plan for emergencies','build capacity before a hazard occurs','capacity包括人员、制度和资源。'),P('warn people','issue an alert','communicate imminent risk','deliver an actionable early warning','actionable强调收到后知道怎么办。'),P('people at risk','exposed residents','vulnerable populations','communities facing elevated disaster risk','vulnerable需说明具体脆弱因素。'),P('recover quickly','accelerate recovery','restore essential functions','reduce the period of disruption','restore functions不等于恢复原貌。'),P('strong building','hazard-resistant structure','building designed to withstand impact','structure compliant with resilient codes','code-compliant更具体。'),P('emergency help','disaster relief','immediate humanitarian assistance','support delivered during the response phase','response与长期recovery区分。'),P('damage gets worse','losses escalate','secondary impacts emerge','initial disruption produces cascading effects','cascading effects适合基础设施连锁故障。')],sentences:[S('A hazard becomes a disaster when + physical event + intersects with + exposed condition.','当天然事件与暴露和脆弱条件相遇时，风险才演变成灾害。','A storm becomes a disaster when extreme winds intersect with fragile housing and limited evacuation options.'),S('Warnings, unless + participle phrase +, may + failure outcome + despite + technical accuracy.','预警如果没有满足某种实际条件，即使技术上准确也可能失效。','Warnings, unless delivered in a language residents understand, may fail despite technical accuracy.'),S('The speed with which + service + is restored can determine whether + initial event + develops into + secondary crisis.','某项服务恢复的速度，可能决定最初事件是否演变成次生危机。','The speed with which drinking water is restored can determine whether a flood develops into a public-health crisis.')],expressions:[E('know what to do in an emergency','知道紧急情况下该做什么','A clear drill helps children know what to do in an emergency.'),E('get back on your feet','重新站稳脚跟','Small grants helped shop owners get back on their feet.'),E('take warnings seriously','认真对待预警','Residents are more likely to take warnings seriously when earlier alerts were accurate.'),E('reduce exposure to hazards','降低对灾害风险源的暴露','Land-use planning can reduce exposure to hazards.'),E('prevent cascading failures','防止连锁故障','Backup power can prevent cascading failures in hospitals.')],mistakes:[M('The earthquake was happened at night.','The earthquake happened at night.','happen是不及物动词，不使用被动语态。'),M('People must escape from the building immediately.','People must evacuate the building immediately.','正式应急语境中evacuate a building更准确；escape强调逃脱。'),M('The disaster caused many damages.','The disaster caused extensive damage.','damage表示损害时通常不可数。')],writingIdeas:[W('Preparedness funding should protect essential systems before disasters.','Investment before a hazard occurs is often more effective than relying solely on emergency relief afterwards.',['strengthen critical infrastructure','conduct preparedness drills','maintain backup systems','avoid cascading failures'],'A severe event becomes more destructive when electricity, water and communication fail together. Reinforced facilities, backup power and rehearsed responsibilities can keep essential services operating during the first critical hours. Although prevention spending lacks the visibility of post-disaster aid, it reduces both human suffering and later reconstruction costs. For example, a functioning clinic can treat injuries before transport routes reopen. Governments should therefore maintain preparedness budgets even during long periods without a major event.'),W('Recovery should address previous vulnerability rather than reproduce it.','Rebuilding the same unsafe conditions leaves communities exposed to the next hazard.',['build back better','enforce resilient standards','restore secure livelihoods','involve affected residents'],'Rapid reconstruction can provide housing and jobs, but speed alone is a poor measure of recovery. If homes return to a floodplain with identical materials, public money recreates the original risk. Safer locations, stronger codes and restored local livelihoods can reduce future losses, although plans must reflect residents’ needs and land rights. Community participation helps distinguish necessary improvement from relocation imposed for unrelated development. Recovery succeeds when people regain stable lives with less vulnerability than before.')],speaking:[{part:'Part 2',question:'Describe an emergency drill or safety exercise you took part in.',answer:'I took part in a fire evacuation drill at work last year. An alarm sounded without advance notice, and everyone had to leave by the stairs and gather at a marked point outside. My role was simply to follow the route and report to the person checking attendance. The exercise revealed that one exit sign was difficult to see from a meeting room and that visitors were not included clearly on the staff list. Those issues were corrected afterwards. The drill was slightly inconvenient, but it made the procedure familiar enough that I would not need to read instructions during a real emergency. I think that practical memory is the main value of an exercise.'},{part:'Part 3',question:'Why do some people ignore disaster warnings?',answer:'They may have experienced earlier alerts that did not lead to visible danger, so repeated caution creates warning fatigue. Others cannot act easily: evacuating may mean leaving animals, losing income or travelling without a car. Messages can also be too technical or arrive through channels that some residents do not use. Authorities need accurate forecasts, but they also need trusted local messengers, clear actions and support for people facing practical barriers. Calling residents irresponsible can hide weaknesses in the warning system itself.'}],reading:{title:'A Warning Is More Than a Forecast',paragraphs:['When a cyclone approaches the coast, meteorologists can estimate its path, wind speed and likely storm surge. Those forecasts are essential, but they do not constitute a complete warning. A warning succeeds only if it reaches people in time, conveys what the danger means for their location and enables an action that is safer than remaining where they are.','A coastal province tested its system during two moderate storms. Text alerts reached most registered phones, yet interviews later found that fishing crews offshore, recent migrants and residents with limited literacy had understood them differently. The message named technical surge heights but did not identify which roads would flood first. Some families delayed leaving because the official shelter, although marked on a map, required transport they did not have.','Before the next storm season, emergency staff worked with local radio presenters, harbour managers and community health workers. They translated thresholds into landmarks—water may cross the market road—and linked each alert level to a specific action. Volunteer drivers received lists of residents who had requested help, while fishing boats could receive short radio instructions beyond mobile coverage. The revised system involved more organisations, which made coordination harder but extended the warning’s practical reach.','False alarms remained unavoidable because a cyclone can change direction after evacuation begins. Officials explained that uncertainty directly rather than promising perfect forecasts. They also reviewed every alert to learn whether a missed prediction arose from limited science or a preventable communication failure. This distinction mattered: improving a model would not solve a message sent in the wrong language, just as clearer wording could not remove uncertainty from the storm track.','The province ultimately judged warnings by protective action, not message delivery. Phone statistics still showed technical reach, but local reports revealed whether households arrived safely and which groups remained excluded. Forecasting identifies a possible future; an effective warning builds a bridge between that knowledge and a decision people can realistically carry out.'],questions:[Q('Multiple Choice','What problem did residents have with the original surge message?','C','It gave technical heights without identifying affected roads.',['It arrived after both storms ended.','It was sent only by radio.','It gave technical heights without identifying affected roads.','It promised free private transport.']),Q('Matching Information','Which paragraph discusses the unavoidable possibility of false alarms?','D','Paragraph D explains that cyclones can change direction.'),Q('Yes / No / Not Given','The writer considers message-delivery statistics sufficient to judge a warning system.','No','The final paragraph says protective action and exclusion must also be assessed.')]}});

set(80,{vocabulary:[V('green infrastructure','/ɡriːn ˈɪnfrəˌstrʌktʃə/','绿色基础设施','invest in green infrastructure','投资绿色基础设施'),V('urban canopy','/ˈɜːbən ˌkænəpi/','城市树冠','expand the urban canopy','扩大城市树冠'),V('permeable surface','/ˈpɜːmiəbəl ˌsɜːfɪs/','透水表面','install a permeable surface','铺设透水表面'),V('rain garden','/ˈreɪn ˌɡɑːdən/','雨水花园','create a roadside rain garden','建设路旁雨水花园'),V('green roof','/ɡriːn ruːf/','绿色屋顶','maintain a green roof','维护绿色屋顶'),V('urban heat island','/ˌɜːbən ˈhiːt aɪlənd/','城市热岛','reduce the urban heat-island effect','缓解城市热岛效应'),V('stormwater runoff','/ˈstɔːmwɔːtə ˌrʌnɒf/','雨水径流','capture stormwater runoff','收集雨水径流'),V('mixed-use development','/ˌmɪkst juːs dɪˈveləpmənt/','混合用途开发','support mixed-use development','支持混合用途开发'),V('walkable neighbourhood','/ˈwɔːkəbəl ˈneɪbəhʊd/','适宜步行的社区','design a walkable neighbourhood','设计适宜步行的社区'),V('pocket park','/ˈpɒkɪt pɑːk/','袖珍公园','turn a vacant site into a pocket park','把空地改为袖珍公园'),V('shade provision','/ʃeɪd prəˈvɪʒən/','遮阴供给','improve shade provision','增加遮阴'),V('active travel','/ˈæktɪv ˌtrævəl/','主动出行','encourage active travel','鼓励步行骑行'),V('nature-based solution','/ˈneɪtʃə beɪst səˌluːʃən/','基于自然的解决方案','adopt a nature-based solution','采用基于自然的方案'),V('maintenance budget','/ˈmeɪntənəns ˌbʌdʒɪt/','维护预算','secure a maintenance budget','确保维护预算'),V('equitable access','/ˈekwɪtəbəl ˈækses/','公平可及','ensure equitable access to green space','确保公平获得绿地'),V('a shady route','/ə ˈʃeɪdi ruːt/','有树荫的路线','choose a shady route','选择有树荫的路线'),V('within a short walk','/wɪˈðɪn ə ʃɔːt wɔːk/','短距离步行可达','live within a short walk of a park','住在步行不远的公园附近'),V('cool down','/kuːl daʊn/','凉快下来','stop under a tree to cool down','在树下停留降温'),V('make room for nature','/meɪk ruːm fə ˈneɪtʃə/','为自然留出空间','make room for nature in dense districts','在密集城区为自然留空间'),V('deliver multiple benefits','/dɪˈlɪvə ˈmʌltɪpəl ˌbenɪfɪts/','带来多重效益','design projects to deliver multiple benefits','设计能带来多重效益的项目')],paraphrases:[P('green city planning','environmentally responsive planning','ecological urban design','planning that integrates natural systems','integrates强调自然不是附加装饰。'),P('more trees','greater tree-canopy cover','an expanded urban forest','increased shade-producing vegetation','canopy cover是可测指标。'),P('absorb rainwater','retain stormwater','slow and capture runoff','allow rainfall to infiltrate','infiltrate指渗入土壤。'),P('easy to walk','pedestrian-friendly','walkable','designed for convenient travel on foot','walkable兼顾距离和环境。'),P('small green space','pocket park','neighbourhood-scale open space','a compact publicly accessible green area','pocket park有明确规划含义。'),P('cool the city','reduce urban heat','moderate local temperatures','mitigate the heat-island effect','mitigate适合正式写作。'),P('fair access','equitable provision','a more even distribution of benefits','access that reflects different levels of need','equitable不等于完全平均。'),P('look after a park','maintain public green space','fund long-term landscape care','manage vegetation and facilities over time','maintenance是长期成本。')],sentences:[S('A green space that is + distance + but separated by + barrier + may be less accessible than + comparison.','一处绿地即使距离很近，如果被障碍隔开，也可能不如更远的绿地易于到达。','A green space that is nearby but separated by a six-lane road may be less accessible than a smaller park along a safe route.'),S('Not only does + green feature + reduce + environmental problem, but it also + social benefit.','某绿色设施不仅缓解环境问题，还能带来社会效益。','Not only does a rain garden reduce runoff, but it also creates a more pleasant walking route.'),S('Planners deciding where to + intervention + should consider + condition, rather than merely + simple metric.','决定在哪里实施干预的规划者应考虑实际条件，而不能只看单一指标。','Planners deciding where to plant trees should consider pedestrian exposure, rather than merely counting available plots.')],expressions:[E('have a park on your doorstep','家门口就有公园','Families value having a park on their doorstep.'),E('take the cooler route','走更凉快的路线','In summer, I take the cooler route under mature trees.'),E('turn grey space green','把灰色空间变绿','The project turned an unused car park from grey space green.'),E('integrate nature into urban design','把自然融入城市设计','New districts should integrate nature into urban design.'),E('deliver social and environmental benefits','带来社会和环境双重效益','A shaded square can deliver social and environmental benefits.')],mistakes:[M('The government should plant more green.','The local authority should create more green space.','green不能这样作可数名词；使用green space或vegetation。'),M('There are fewer shadow in this street.','There is less shade on this street.','shade通常不可数，搭配less。'),M('The park is convenient for arriving.','The park is easy to reach.','表达地点容易到达，natural English用easy to reach。')],writingIdeas:[W('Green infrastructure should be planned as essential infrastructure.','Urban nature can manage heat and water while improving daily public space.',['manage stormwater runoff','expand tree-canopy cover','provide usable shade','deliver multiple benefits'],'A drainage pipe performs one main function, whereas a well-placed rain garden can slow runoff, cool a street and improve the pedestrian environment. These additional benefits justify treating green infrastructure as part of core urban systems rather than optional decoration. However, performance depends on soil, species choice and long-term maintenance, so visual appeal alone is insufficient. Cities should specify measurable functions and fund care from the beginning. When technical and social goals are coordinated, one intervention can solve several local problems.'),W('Green investment should be directed by need, not available space alone.','Planting where implementation is easiest can reinforce existing inequalities in heat exposure and park access.',['map heat vulnerability','prioritise underserved areas','remove access barriers','distribute benefits equitably'],'Affluent districts often have wide pavements and mature parks, making additional planting straightforward. Dense lower-income areas may need trees more urgently but require road redesign, utility relocation or land purchase. If planners count only the number planted, they may choose easy sites and miss residents facing the greatest heat risk. Combining temperature data with age, housing and pedestrian routes can identify priority locations. Higher costs in these areas may be justified because equitable planning responds to need rather than distributing identical inputs.')],speaking:[{part:'Part 2',question:'Describe a green public space that is useful to local people.',answer:'There is a small park beside a busy shopping street that local people use in several ways. It has mature trees, benches, a drinking fountain and a simple play area, so office workers, parents and older residents all spend time there. I often stop for lunch because the shade makes it noticeably cooler than the surrounding pavement. The park is not large enough for sport, but it connects two pedestrian routes and provides a quiet pause between shops and traffic. What makes it successful is not spectacular landscaping; it is the combination of location, shade and basic facilities. It shows that a modest green space can be valuable when it responds to everyday routines.'},{part:'Part 3',question:'What makes an urban green project successful in the long term?',answer:'The design has to suit the site, but maintenance and public use are equally important. A tree species may look attractive yet fail if there is too little soil or no budget for watering during its first years. Residents also need safe routes into the space and reasons to use it at different times. Clear responsibility for pruning, drainage and repairs should be agreed before construction. Finally, success should be measured through shade, biodiversity, water management and access, not just by counting how many plants were installed on opening day.'}],reading:{title:'The Unequal Geography of Urban Shade',paragraphs:['A city announced that it would plant one hundred thousand trees, presenting the total as both a climate target and a public-health investment. The number was ambitious, but a preliminary map exposed a difficulty: districts with the fewest trees also offered the narrowest pavements, the greatest concentration of underground utilities and the smallest municipal planting budgets. Equal numbers for every district would not produce equal shade.','Tree canopy is usually measured from above, yet residents experience it along particular routes and at particular times. A large private garden can raise a neighbourhood’s canopy percentage without shading a bus stop, while one street tree may protect hundreds of pedestrians during an afternoon heatwave. Planners therefore combined aerial imagery with surface temperatures, walking routes and the locations of schools, clinics and older residents.','The revised programme assigned priority to places where heat exposure and pedestrian use overlapped. In some streets, planting required removing parking spaces and constructing larger soil pits, decisions that were more expensive and politically difficult than adding trees to an existing park. Elsewhere, awnings provided immediate shade while slower-growing trees became established. This mixed approach acknowledged that a planting target, although easy to communicate, was not itself a complete heat strategy.','Maintenance introduced another inequality. Young trees in hotter, paved districts needed more water and were more vulnerable to damage. Funding based only on the number of trees would leave precisely those sites with insufficient care. The city consequently allocated early maintenance according to local growing conditions and published survival rates by district, not merely a citywide total.','Five years is too soon to judge the mature canopy, but it is long enough to learn what survives and whom the programme serves. The initiative still counts trees; counting enables accountability. Its more meaningful question, however, is whether shade appears where people who are most exposed can actually use it. In green urban planning, location, route and time can matter as much as the total visible from the sky.'],questions:[Q('True / False / Not Given','Private gardens can increase canopy statistics without shading public routes.','True','Paragraph 2 gives this exact contrast.'),Q('Multiple Choice','Why were awnings used in some places?','B','They supplied immediate shade while trees grew.',['They were cheaper than collecting data.','They supplied immediate shade while trees grew.','They increased private garden area.','They removed the need for maintenance.']),Q('Sentence Completion','The city published tree survival rates by ______ rather than only as a citywide total.','district','Paragraph 4 states this directly.')]}});

